catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (newValue == '') {
        return;
    }

    var ga = new GlideAjax("x_hccc_hoc_ohs.HoCOHSMUtils");
    ga.addParam("sysparm_name", "getParentOHSMDetails");
    ga.addParam("sysparm_task_num", newValue);
    ga.getXMLAnswer(getParentDetails);


    function getParentDetails(response) {
        var result = JSON.parse(response); //transform the JSON string to an object

        g_form.setValue("inc_date_time", result.inc_date_time);
        g_form.setValue("inc_location", result.inc_location);
        g_form.setValue("refusal_reason", result.refusal_reason);
        g_form.setValue("inc_refusal_loc", result.inc_refusal_loc);
        g_form.setValue("rw_decision", result.rw_decision);
        g_form.setValue("rw_event_refusal", result.rw_event_refusal);
        g_form.setValue("rw_corrective_action", result.rw_corrective_action);
        g_form.setValue("rw_investigation_details", result.rw_investigation_details);

    }
}
